import re
for f in ['nb4_s5501.log','nb4_s5502.log','nb4_s5503.log','nb4_s5504.log']:
    pts=[]
    for l in open(f,errors='replace'):
        m=re.search(r'prod kpi.* t=(\d+):(\d+) money=(\d+)',l)
        if m: pts.append((int(m.group(1)),int(m.group(3))))
    print(f,' '.join('%dm:%.2g'%(t,v) for t,v in pts[::10]))
